<?php
require_once __DIR__.'/../app/layout.php';
$u=require_login();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id)forbidden();
$o=get_order((int)$id,$u);if($o['status']!=='completed'||$o['paid_amount']===null)forbidden();
