?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Receipt · <?=e($o['order_no'])?></title><link rel="stylesheet" href="<?=e(url('assets/css/style.css'))?>"></head><body class="receipt-body"><div class="receipt-wrap"><div class="receipt-actions"><a class="btn btn-outline" href="<?=e(url($u['role']==='admin'?'admin/order.php?id='.$id:'customer/order.php?id='.$id))?>">← Back to order</a><button class="btn btn-primary" onclick="window.print()">Print receipt</button></div><section class="receipt-paper"><div class="receipt-brand"><span class="receipt-logo"><?=svg_icon('printer')?></span><h1>PrintFlow</h1><p>PRINTING SERVICE RECEIPT</p></div><div class="receipt-paid">PAID IN FULL</div><div class="receipt-pair"><span>Order number</span><strong><?=e($o['order_no'])?></strong></div><div class="receipt-pair"><span>Customer</span><strong><?=e($o['customer_name'])?></strong></div><div class="receipt-pair"><span>Paid on</span><strong><?=e(nice_date($o['paid_at']))?></strong></div><div class="receipt-pair"><span>Processed by</span><strong><?=e($admin?:'Administrator')?></strong></div><hr><div class="receipt-pair"><span>Paper / Color</span><strong><?=e($o['paper_size'])?> / <?=$o['print_color']==='bw'?'B&W':'Color'?></strong></div><div class="receipt-pair"><span>Print sides</span><strong><?=$o['sides']==='double'?'Double-sided':'Single-sided'?></strong></div><div class="receipt-pair"><span>Pages × Copies</span><strong><?=$o['pages_per_copy']?> × <?=$o['copies']?></strong></div><div class="receipt-pair"><span>Rate per page</span><strong><?=money($o['unit_price_snapshot'])?></strong></div><hr><div class="receipt-total"><span>TOTAL PAID</span><strong><?=money($o['paid_amount'])?></strong></div><p class="receipt-thanks">Thank you for printing with PrintFlow!</p></section></div></body></html>
